21	
22	    private CustomerCode() {
23	    }
24	
25	    /** The {@code '<REGION>-<HASH8>'} code for {@code region}, {@code normalizedTelephone} and {@code lastName}. */
26	    public static String of(String region, String normalizedTelephone, String lastName) {
27	        return region + "-" + hash8(normalizedTelephone, lastName);
28	    }
29	
30	    /** First 8 UPPER-case hex characters of SHA-256 over {@code normalizedTelephone + lastName}. */
31	    public static String hash8(String normalizedTelephone, String lastName) {
32	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
33	                + (lastName == null ? "" : lastName);
34	        try {
35	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
36	            StringBuilder sb = new StringBuilder(8);
37	            for (int i = 0; i < 4; i++) {
38	                sb.append(String.format("%02X", digest[i]));
39	            }
40	            return sb.toString();
41	        }
42	        catch (NoSuchAlgorithmException ex) {
43	            throw new IllegalStateException("SHA-256 not available", ex);
44	        }
45	    }
46	
47	    /**
48	     * The owner's locality: the REGION part of its {@code customerCode} ({@code '<REGION>-<HASH8>'}).
49	     * When the owner has no customerCode (e.g. seed data not created through the endpoint), falls back
50	     * to deriving the region straight from postcode/city via {@link CityRegion}.
51	     */
52	    public static String locality(Owner owner) {
53	        String code = owner.getCustomerCode();
54	        if (code != null) {
55	            int dash = code.indexOf('-');
56	            if (dash > 0) {
