3	/**
4	 * Computes the Luhn check digit over the digits contained in a string.
5	 *
6	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so MapStruct does
7	 * not mistake it for a mapping method and apply it to unrelated fields.
8	 */
9	public final class CheckDigit {
10	
11	    private CheckDigit() {
12	    }
13	
14	    /**
15	     * The Luhn check digit (0-9) over the digits contained in {@code s}, or {@code null} when
16	     * {@code s} is {@code null}. Non-digit characters are ignored.
17	     */
18	    public static Integer luhn(String s) {
19	        if (s == null) {
20	            return null;
21	        }
22	        int sum = 0;
23	        boolean dbl = true;
24	        for (int i = s.length() - 1; i >= 0; i--) {
25	            char c = s.charAt(i);
26	            if (c < '0' || c > '9') {
27	                continue;
28	            }
29	            int d = c - '0';
30	            if (dbl) {
31	                d *= 2;
32	                if (d > 9) {
33	                    d -= 9;
34	                }
35	            }
36	            sum += d;
37	            dbl = !dbl;
38	        }
39	        return (10 - (sum % 10)) % 10;
40	    }
41	}
