7	/**
8	 * Derives fiscal-year values from a date. The fiscal year starts on 1 July, so a date from 1 July
9	 * onward belongs to the fiscal year that ends the following 30 June; a date up to 30 June belongs to
10	 * the fiscal year ending that 30 June. Each fiscal year is labelled by the calendar year it ends in.
11	 *
12	 * <p>All date-derived owner values sit on this basis: the {@code fiscalYear} label, the membership
13	 * number's year segment and the tenure count (elapsed fiscal years) are all taken from the owner's
14	 * business-day-adjusted {@code registrationDate}.
15	 *
16	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so MapStruct does not
17	 * mistake it for a mapping method and apply it to unrelated fields.
18	 */
19	public final class FiscalYear {
20	
21	    private FiscalYear() {
22	    }
23	
24	    /**
25	     * The fiscal year that {@code date} falls in, identified by the calendar year it ends in: the same
26	     * calendar year for a date up to 30 June, the next calendar year for a date from 1 July onward.
27	     */
28	    public static int endingYear(LocalDate date) {
29	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
30	    }
31	
32	    /**
33	     * The {@code 'FY<YY>'} label of {@code owner}'s registration fiscal year (YY being the last two
34	     * digits of the {@link #endingYear(LocalDate) ending year}), or {@code null} when the owner has no
35	     * registration date.
36	     */
37	    public static String label(Owner owner) {
38	        LocalDate registrationDate = owner.getRegistrationDate();
39	        if (registrationDate == null) {
40	            return null;
41	        }
42	        return "FY" + yearSegment(registrationDate);
43	    }
44	
45	    /**
46	     * The two-digit year segment of {@code date}'s fiscal year, used for both the {@code fiscalYear}
47	     * label and the membership number's year segment.
48	     */
49	    public static String yearSegment(LocalDate date) {
50	        return String.format("%02d", endingYear(date) % 100);
51	    }
52	
53	    /**
54	     * The number of whole fiscal years elapsed between {@code owner}'s registration date and today, i.e.
55	     * the number of 1-July boundaries crossed. Zero when the owner has no registration date.
56	     */
57	    public static int elapsedYears(Owner owner) {
58	        LocalDate registrationDate = owner.getRegistrationDate();
59	        if (registrationDate == null) {
60	            return 0;
61	        }
62	        return endingYear(LocalDate.now()) - endingYear(registrationDate);
63	    }
64	}
