5	/**
6	 * Derives the canonical region (locality) for a city from a fixed city-to-region table.
7	 *
8	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so MapStruct does
9	 * not mistake it for a {@code String -> String} mapping method and apply it to unrelated fields.
10	 */
11	public final class CityRegion {
12	
13	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
14	    private static final Map<String, String> CITY_REGION = Map.of(
15	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
16	
17	    /** Region -> inclusive {low, high} 4-digit postcode range. */
18	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
19	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
20	
21	    /** Region -> IANA timezone name. */
22	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
23	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
24	
25	    private CityRegion() {
26	    }
27	
28	    /**
29	     * The canonical region, preferring the postcode: if {@code postcode} is a 4-digit code inside a
30	     * known region's range it wins, disambiguating cities that share a name. Otherwise (postcode
31	     * absent or in no known range) fall back to the city-to-region table, or "UNKNOWN".
32	     */
33	    public static String locality(String postcode, String city) {
34	        String byPostcode = regionForPostcode(postcode);
35	        return byPostcode != null ? byPostcode : locality(city);
36	    }
37	
38	    /** The canonical region for {@code city}, or "UNKNOWN" when the city is not in the table. */
39	    public static String locality(String city) {
40	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
41	    }
42	
43	    /**
44	     * The IANA timezone name for {@code region} via the fixed region-to-timezone table
45	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null}
46	     * when the region is not one of these.
47	     */
48	    public static String timezone(String region) {
49	        return REGION_TIMEZONE.get(region);
50	    }
51	
52	    /** The region whose postcode range contains {@code postcode}, or {@code null} if none does. */
53	    private static String regionForPostcode(String postcode) {
54	        if (postcode == null || !postcode.matches("\\d{4}")) {
55	            return null;
56	        }
57	        int code = Integer.parseInt(postcode);
58	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
59	            int[] range = entry.getValue();
60	            if (code >= range[0] && code <= range[1]) {
61	                return entry.getKey();
62	            }
63	        }
64	        return null;
65	    }
66	
67	    /**
68	     * The inclusive {@code {low, high}} 4-digit postcode range valid for {@code city}'s region, or
69	     * {@code null} when the city has no known region (in which case any 4-digit postcode is valid).
70	     */
71	    public static int[] postcodeRange(String city) {
72	        return REGION_POSTCODES.get(locality(city));
73	    }
74	}
