5	/**
6	 * Scores an owner's membership from its profile completeness and its tenure, then maps that score to
7	 * a membership level.
8	 *
9	 * <p>Points start at 0 and accrue per factor: add 2 for a contactable email, add 1 for a unique name
10	 * ({@code namesakeCount} of 0), add 2 for belonging to a household of three or more members, and add
11	 * 3 for a tenure of more than one elapsed fiscal year since the owner's registration date.
12	 *
13	 * <p>The points then map to a level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
14	 *
15	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so MapStruct does not
16	 * mistake it for a mapping method and apply it to unrelated fields.
17	 */
18	public final class MembershipLevel {
19	
20	    private MembershipLevel() {
21	    }
22	
23	    /**
24	     * The membership points of {@code owner}: 0 plus 2 for an email, 1 for a unique name, 2 for a
25	     * household of three or more, and 3 for more than one elapsed fiscal year of tenure.
26	     */
27	    public static int points(Owner owner) {
28	        int points = 0;
29	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
30	            points += 2;
31	        }
32	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
33	            points += 1;
34	        }
35	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
36	            points += 2;
37	        }
38	        if (FiscalYear.elapsedYears(owner) > 1) {
39	            points += 3;
40	        }
41	        return points;
42	    }
43	
44	    /**
45	     * The membership level of {@code owner}, derived from its {@link #points(Owner) points}: 1 for
46	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
47	     */
48	    public static int of(Owner owner) {
49	        int points = points(owner);
50	        if (points <= 1) {
51	            return 1;
52	        }
53	        if (points <= 3) {
54	            return 2;
55	        }
56	        if (points <= 5) {
57	            return 3;
58	        }
59	        return 4;
60	    }
61	
62	    /**
63	     * The effective membership level of {@code owner}: the level captured on the owner at creation
64	     * (the household-capped value stored in {@code membershipLevel}) when present, otherwise the
65	     * freshly {@link #of(Owner) computed} level. Owners created before the cap existed (e.g. seed
66	     * data) have no stored level and fall back to the computed value.
67	     */
68	    public static int effective(Owner owner) {
69	        Integer stored = owner.getMembershipLevel();
70	        return stored != null ? stored : of(owner);
71	    }
72	}
