2	
3	/**
4	 * Immutable structured audit event emitted once per created owner.
5	 *
6	 * <p>Rendered to AUDIT as the compact JSON object
7	 * {@code {seq, ownerId, customerCode, membershipLevel, event:"OWNER_CREATED"}}. {@code seq} is a
8	 * monotonically increasing integer across creates (see {@link AuditOwnerCreated}).
9	 *
10	 * <p>The {@code identifier} carries the owner's <em>current primary identifier</em>: the
11	 * customerCode today, and whatever replaces it later. When the customerCode is unified into the
12	 * memberId, only {@link AuditOwnerCreated} needs to source the identifier from the memberId — the
13	 * event still renders it under the primary-identifier key, so the wire shape follows the identity.
14	 */
15	public record OwnerCreatedEvent(long seq, int ownerId, String identifier, int membershipLevel) {
16	
17	    /** The event type marker. */
18	    public static final String EVENT = "OWNER_CREATED";
19	
20	    /** The JSON key for the primary identifier — {@code customerCode} while that is the identity. */
21	    private static final String IDENTIFIER_KEY = "customerCode";
22	
23	    /**
24	     * Compact, deterministic JSON:
25	     * {@code {"seq":..,"ownerId":..,"customerCode":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
26	     */
27	    public String toJson() {
28	        return "{\"seq\":" + this.seq
29	                + ",\"ownerId\":" + this.ownerId
30	                + ",\"" + IDENTIFIER_KEY + "\":" + json(this.identifier)
31	                + ",\"membershipLevel\":" + this.membershipLevel
32	                + ",\"event\":\"" + EVENT + "\"}";
33	    }
34	
35	    /** JSON-encode a nullable string value (bare {@code null}, otherwise a quoted, escaped string). */
36	    private static String json(String value) {
37	        if (value == null) {
38	            return "null";
39	        }
40	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
41	        for (int i = 0; i < value.length(); i++) {
42	            char c = value.charAt(i);
43	            switch (c) {
44	                case '"' -> sb.append("\\\"");
45	                case '\\' -> sb.append("\\\\");
46	                case '\n' -> sb.append("\\n");
47	                case '\r' -> sb.append("\\r");
48	                case '\t' -> sb.append("\\t");
49	                default -> sb.append(c);
50	            }
51	        }
52	        return sb.append('"').toString();
53	    }
54	}
