3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	/**
11	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is expressed
12	 * through:
13	 *
14	 * <pre>identityKey = SHA-256 hex over (normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))</pre>
15	 *
16	 * <p>The three components are joined with {@code '|'} and hashed with SHA-256, yielding a 64-character
17	 * lower-case hex string. The telephone is normalized to its E.164 form (see {@link E164Telephone}); a
18	 * value that cannot form a valid E.164 number is used verbatim so the key stays defined for every
19	 * stored owner. The email contributes its lower-cased form, or the empty string when absent. The last
20	 * name contributes its {@link Soundex} code, so phonetically identical surnames share this component.
21	 *
22	 * <p>Two owners are duplicates only when their WHOLE identityKey is equal. Because the telephone is
23	 * part of the key, owners with the same surname (and postcode) but different telephones have
24	 * different keys and are both allowed — they are flagged as a soft match rather than rejected.
25	 */
26	public final class IdentityKey {
27	
28	    private IdentityKey() {
29	    }
30	
31	    public static String of(Owner owner) {
32	        String raw = normalizeTelephone(owner.getTelephone()) + "|" + normalizeEmail(owner.getEmail())
33	                + "|" + Soundex.of(owner.getLastName());
34	        return sha256Hex(raw);
35	    }
36	
37	    private static String sha256Hex(String value) {
38	        try {
39	            byte[] digest = MessageDigest.getInstance("SHA-256")
40	                    .digest(value.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(digest.length * 2);
42	            for (byte b : digest) {
43	                sb.append(String.format("%02x", b));
44	            }
45	            return sb.toString();
46	        }
47	        catch (NoSuchAlgorithmException e) {
48	            throw new IllegalStateException("SHA-256 not available", e);
49	        }
50	    }
51	
52	    private static String normalizeTelephone(String telephone) {
53	        try {
54	            return E164Telephone.normalize(telephone);
55	        }
56	        catch (InvalidTelephoneException ex) {
57	            return telephone == null ? "" : telephone;
58	        }
59	    }
60	
61	    private static String normalizeEmail(String email) {
62	        return email == null || email.isBlank() ? "" : email.toLowerCase();
63	    }
64	}
