12	public class AuditOwnerCreated {
13	
14	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
15	
16	    /** Monotonically increasing sequence number across all created owners. */
17	    private static final AtomicLong SEQ = new AtomicLong();
18	
19	    public void service(@Val Owner owner) {
20	        String membershipNumber = owner.getCustomerCode() == null || owner.getRegistrationDate() == null
21	                ? null
22	                : owner.getCustomerCode() + "-M" + FiscalYear.yearSegment(owner.getRegistrationDate());
23	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
24	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
25	                MembershipLevel.of(owner), membershipNumber);
26	
27	        // Immutable structured event carrying the owner's current primary identifier. Today that is
28	        // the customerCode; when it is unified into the memberId, source the identifier there instead.
29	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
30	                primaryIdentifier(owner), MembershipLevel.effective(owner));
31	        AUDIT.info(event.toJson());
32	    }
33	
34	    /** The owner's current primary identifier — the customerCode while that is the identity. */
35	    private static String primaryIdentifier(Owner owner) {
36	        return owner.getCustomerCode();
37	    }
38	}
