1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Consolidated duplicate detection for {@code POST /api/owners}: rejects a create with 409 via
10	 * {@link DuplicateIdentityException} only when the new owner's WHOLE {@code identityKey} (see
11	 * {@link IdentityKey}) — the SHA-256 hex over {@code normalizedTelephone|lowerEmail|soundex(lastName)}
12	 * — equals an existing owner's, i.e. the same telephone, email and phonetic surname. The identityKey
13	 * is the single identity rule: the computed householdId plays no part here, so two owners with the
14	 * same surname and postcode but different telephones have different keys and are both allowed (they
15	 * are surfaced as a soft match by {@link FlagPossibleDuplicate}). This is what lets a household
16	 * accumulate members for the membership-level cap (see {@link CapMembershipLevel}). Only a truly
17	 * identical identity is a conflict.
18	 *
19	 * <p>Runs after {@link AssignHousehold} and before {@link SaveOwner}. The email-domain blocklist
20	 * ({@link RejectDisposableEmailDomain}) has already applied earlier in the pipeline. Soft-deleted
21	 * owners no longer block a create.
22	 */
23	public class EnsureUniqueIdentity {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        String identityKey = IdentityKey.of(owner);
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
30	                continue; // the owner being created is not yet its own duplicate
31	            }
32	            if (Boolean.TRUE.equals(existing.getDeleted())) {
33	                continue; // a soft-deleted owner no longer blocks a create
34	            }
35	            if (IdentityKey.of(existing).equals(identityKey)) {
36	                throw new DuplicateIdentityException(identityKey);
37	            }
38	        }
39	    }
40	}
