2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.MembershipLevel;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Step of {@code POST /api/owners} that captures the owner's household-capped {@code membershipLevel}.
10	 *
11	 * <p>The owner's naturally {@link MembershipLevel#of(Owner) computed} level cannot exceed one above
12	 * the current maximum {@link MembershipLevel#effective(Owner) effective} level among the existing
13	 * members of its household (owners sharing the same {@code householdId}, which is not yet the owner
14	 * being created). When the owner has no household or has no existing household member, no cap applies
15	 * and the natural level is stored verbatim.
16	 *
17	 * <p>Runs after {@link AssignHouseholdSize} and {@link AssignNamesakeCount} so the inputs the natural
18	 * level depends on (household size, namesake count, email, registration date) are finalized, and
19	 * before {@link SaveOwner} so the captured level is persisted with the owner. The stored value is what
20	 * {@code OwnerMapper} later returns as {@code membershipLevel}.
21	 */
22	public class CapMembershipLevel {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        int natural = MembershipLevel.of(owner);
26	        String householdId = owner.getHouseholdId();
27	        if (householdId == null) {
28	            owner.setMembershipLevel(natural);
29	            return;
30	        }
31	        Integer maxExisting = null;
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (householdId.equals(existing.getHouseholdId())) {
34	                int level = MembershipLevel.effective(existing);
35	                if (maxExisting == null || level > maxExisting) {
36	                    maxExisting = level;
37	                }
38	            }
39	        }
40	        owner.setMembershipLevel(maxExisting == null ? natural : Math.min(natural, maxExisting + 1));
41	    }
42	}
